# ---- kit check= hooks of the 3 rows
M(cfg, r"""
public static String checkPrefix(String key, String value) {
  if (value == null) return null;
  String[] a = splitList(value);
  if (a.length > 8) return "At most 8 name starts.";
  for (int i = 0; i < a.length; i++) {
    String l = a[i].toLowerCase();
    if (!l.matches("[a-z0-9_.-]{4,64}")) return "'" + a[i] + "' is not the start of a world folder name (4-64 of letters, digits, _ . -).";
    if ("@NEVER@".startsWith(l) || l.startsWith("@NEVER@")) return "'" + a[i] + "' would match players' island worlds (@NEVER@...) - islands are never regrow areas.";
  }
  return null;
}""".replace("@NEVER@", NEVER_PREFIX))
M(cfg, r"""
public static String checkPTypes(String key, String value) {
  if (value == null) return null;
  String[] a = splitList(value);
  if (a.length > 32) return "At most 32 types.";
  for (int i = 0; i < a.length; i++) {
    String t = a[i].toLowerCase();
    if (!t.matches("[a-z0-9_]{1,32}")) return "A type id is 1-32 of a-z, 0-9 and _.";
    if (noZ3(t)) return t + " cannot grow back yet (whole trees and crop stages come in a later version).";
    if (!TYPES.isEmpty() && !TYPES.containsKey(t)) return "No resource type '" + t + "' (Server Setup -> Zones -> Resource types).";
    String ph = PPH == null ? "" : PPH.trim();
    if (ph.length() > 0 && @PKG@.ZRules.typeHas(t, @PKG@.ZRules.bare(ph))) return "The placeholder " + ph + " is a block of " + t + " - change the placeholder first.";
  }
  return null;
}""")
M(cfg, r"""
public static String checkPPh(String key, String value) {
  if (value == null) return null;
  String ph = value.trim();
  if (ph.length() == 0 || ph.equalsIgnoreCase("none")) return null;
  if (!ph.matches("[A-Za-z0-9_]{1,80}")) return "'" + ph + "' is not a block id.";
  String lt = prefixListed(ph);
  if (lt != null) return ph + " is a block of the type " + lt + " - players could mine it at once. Pick a block none of those types lists.";
  try {
    Object m = @BTY@.getAssetMap();
    if (m != null && @BTY@.getAssetMap().getIndex(ph) == Integer.MIN_VALUE) return "No block '" + ph + "' in the game files.";
  } catch (Throwable t) { }
  return null;
}""")
